        &workflow,
        RuntimePolicy::Strict,
        &[contract],
        &[pack],
    )?;
    assert_eq!(artifact.accepted_at_seq.get(), 1);
    let counter_after = read_counter(&journal)?;
    assert_eq!(counter_after, Some(1));
    Ok(())
}

