    let (_path, journal) = open_test_journal()?;
    let workflow = action_workflow()?;
    let contract = action_contract()?;
    let scope = register_scope();
    let pack = catalog.register_pack(&contract, scope, vb_core::action_pack::RecoveryClass::Blocked)?;

    journal.fail_next_persist_for_test();

    let result = catalog.submit_artifact(
        &journal,
        &workflow,
        RuntimePolicy::Strict,
        &[contract],
        &[pack],
    );
    match &result {
        Err(ExecutorError::Artifact(JournalError::StrictDurabilityFailed)) => {}
        other => return Err(format!("expected StrictDurabilityFailed, got: {other:?}").into()),
    }

    let counter = read_counter(&journal)?;
    assert_eq!(counter, None);
    assert_eq!(compiled_ir_has_entries(&journal)?, false);

