#[test]
fn malformed_counter_yields_malformed_keyspace_row() -> Result<(), Box<dyn std::error::Error>> {
    let catalog = ExecutorCatalog::run_registered_conformance()?;
    let (_path, journal) = open_test_journal()?;
    let workflow = action_workflow()?;
    let contract = action_contract()?;
    let scope = register_scope();
    let pack = catalog.register_pack(&contract, scope, vb_core::action_pack::RecoveryClass::Blocked)?;

    journal
        .artifact_acceptance
        .insert(b"last_issued", &[1, 2, 3, 4, 5, 6, 7])?;

    let result = catalog.submit_artifact(
        &journal,
        &workflow,
        RuntimePolicy::Relaxed,
        &[contract],
        &[pack],
    );
    match &result {
        Err(ExecutorError::Artifact(JournalError::MalformedKeyspaceRow {
            prefix,
            expected_len,
            actual_len,
        })) if prefix == "0" && expected_len == 8 && actual_len == 7 => {}
        other => {
            return Err(
                format!("expected MalformedKeyspaceRow prefix=0 expected=8 actual=7, got: {other:?}")
