fn require_conflict(result: Result<RegisterReceipt, ExecutorError>) -> Result<(), ExecutorError> {
    match result {
        Err(ExecutorError::ReceiptConflict) => Ok(()),
        Err(other) => Err(other),
        Ok(_) => Err(ExecutorError::Conformance),
    }
