    let result = catalog.submit_artifact(
        &tj.journal,
        &workflow,
        RuntimePolicy::Relaxed,
        contract_slice(&contract),
        pack_slice(&pack),
    );
    match &result {
        Err(ExecutorError::Artifact(JournalError::SequenceOverflow)) => {}
